    ["Type a name here before creating or copying a profile."] = "Geben Sie hier einen Namen ein, bevor Sie ein Profil erstellen oder kopieren.",
    ["Undo"] = "Rückgängig machen",
    ["Unit Auras controls unitframe auras. Group Buffs & Debuffs controls group-frame aura layout, filtering, cooldowns, and private auras."] = "Unit Auras steuert die Unitframe-Auren. Gruppen-Buffs und -Debuffs steuern das Aura-Layout, die Filterung, die Abklingzeiten und die privaten Auren des Gruppenrahmens.",
    ["Unit Frame Preview"] = "Einheitenrahmenvorschau",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "Auf jeder Geräteseite befinden sich Statussymbole für den Geräterahmen. Gruppenrahmenindikatoren finden Sie unter Gruppenrahmen > Indikatoren.",
    ["Unit private aura controls are in Unit Auras > Private Auras. Group-frame private auras are in Group Frames > Buffs & Debuffs > Private Auras."] = "Die Steuerung der privaten Aura der Einheit erfolgt unter „Einheitsauren“ > „Private Auren“. Private Auren im Gruppenrahmen finden Sie unter Gruppenrahmen > Buffs & Debuffs > Private Auren.",
    ["Unitframes"] = "Unitframes",
    ["Urgent"] = "Dringend",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "Verwenden Sie /msuf, um MSUF2 zu öffnen. Das Dashboard enthält außerdem Reset-, Support-, Profil- und Skalierungstools.",
    ["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "Verwenden Sie Dashboard > Positionen zurücksetzen für Frame-Mover. Verwenden Sie Profile nur, wenn Sie Profildaten zurücksetzen, kopieren, importieren oder ersetzen möchten.",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "Verwenden Sie „Globaler Stil“ > „Balken“ für Hervorhebungsränder und „Gruppenrahmen“ > „Indikatoren“ für Rollen-, Bedrohungs-, Bannungs-, Zauber-, Ecken- und Schlachtzugsmarkierungsindikatoren.",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "Verwenden Sie Gruppenrahmen > Layout für Größe und Abstand, Buffs und Debuffs für Aura-Unordnung und Indikatoren für Statussymbole mit fester Position.",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "Verwenden Sie Gruppenrahmenseiten: Layout für Größe/growth/sorting, Gesundheit und Text für Balken/text, Buffs und Debuffs für Auren und Indikatoren für Statussymbole.",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "Verwenden Sie den MSUF-Bearbeitungsmodus, um einen einzelnen Einheitsrahmen zu ziehen. Verwenden Sie die Einheitenseite > Verankerung, wenn Sie genaue Ankerziele oder X/Y-Werte benötigen.",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "Verwenden Sie den MSUF-Bearbeitungsmodus, um unterstützte Besetzungsleisten zu ziehen. Castbar-Enable/icon/text-Optionen pro Einheit finden Sie auf jeder Einheitenseite. Der gemeinsame Castbar-Stil befindet sich unter „Globaler Stil“ > „Castbar“.",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "Verwenden Sie den MSUF-Bearbeitungsmodus, um den Player-Rahmen zu ziehen. Für genaue Anker- oder X/Y-Werte öffnen Sie anschließend Player > Anchoring.",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "Verwenden Sie die Dashboard-Skalierungssteuerelemente für die Menüskalierung oder die UI-Skala. Sie können die Größe des MSUF2-Fensters auch von seiner Ecke aus ändern.",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "Verwenden Sie die Einheitenseite zum Umschalten der Besetzungsleiste pro Einheit und „Globaler Stil“ > „Besetzungsleiste“ für gemeinsame Texturen, Richtung, GCD, Text und Unterbrechungsoptionen.",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "Verwenden Sie dies, wenn HP Bar Fade dazu führt, dass der leere Gesundheitsbereich verschwindet oder schwarz aussieht. Es behält die gleiche HP-Spurfarbe von Colors bei.",
    ["Value:"] = "Wert:",
    ["Version:"] = "Version:",
    ["View"] = "Ansicht",
    ["Welcome to Class Resources!"] = "Willkommen bei den Klassenressourcen!",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW blockiert einige geschützte Frame-Änderungen im Kampf. Verlassen Sie den Kampf und wenden Sie dann Layout-, Verankerungs-, Enable/disable-, Profil- oder geschützte Frame-Änderungen an.",
    ["[2]"] = "[2]",
    ["aggro"] = "aggro",
    ["bottom"] = "unten",
    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "Klassenressourcen-Layout, Verhalten, Stil, automatisches Ausblenden, abgetrennte Energieleiste und alternative Manaeinstellungen",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "Klicken Sie auf Ebenen, um sie auszublenden. Ziehen Sie Vorschauelemente. Pfeile verschieben die Auswahl",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "Rahmenfarben, class/NPC-Farben, Power-Farben, Castbar-Farben, Aura-Farben und Gameplay-Farbeinstellungen",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "Gameplay-Verbesserungseinstellungen wie Kampftext, Fadenkreuz und Click-Cast-Verhalten",
    ["gf_bars"] = "gf_bars",
