    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "Verhalten der Sprache/menu, Aktualisierungsgeschwindigkeit, Tooltips, Handhabung von Blizzard-Frames, Minikartensymbol, Sounds und Einstellungen für die Bereichsüberblendung",
    ["none"] = "keine",
