    ["Top"] = "arriba",
    ["Type a name here before creating or copying a profile."] = "Escriba un nombre aquí antes de crear o copiar un perfil.",
    ["Undo"] = "Deshacer",
    ["Unit Auras controls unitframe auras. Group Buffs & Debuffs controls group-frame aura layout, filtering, cooldowns, and private auras."] = "Unit Auras controla las auras de unidades. Las ventajas y desventajas grupales controlan el diseño del aura del marco grupal, el filtrado, los tiempos de reutilización y las auras privadas.",
    ["Unit Frame Preview"] = "Vista previa del marco de la unidad",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "Los iconos de estado del marco de la unidad se encuentran en cada página de la unidad. Los indicadores del marco de grupo se encuentran en Marcos de grupo > Indicadores.",
    ["Unit private aura controls are in Unit Auras > Private Auras. Group-frame private auras are in Group Frames > Buffs & Debuffs > Private Auras."] = "Los controles de aura privada de la unidad se encuentran en Auras de unidad > Auras privadas. Las auras privadas del marco de grupo están en Marcos de grupo > Mejoras y desventajas > Auras privadas.",
    ["Unitframes"] = "Marcos unitarios",
    ["Urgent"] = "Urgente",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "Utilice /msuf para abrir MSUF2. El Panel también contiene herramientas de reinicio, soporte, perfil y escala.",
    ["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "Utilice Panel > Restablecer posiciones para mover marcos. Utilice Perfiles solo cuando desee restablecer, copiar, importar o reemplazar datos de perfil.",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "Utilice Estilo global > Barras para resaltar bordes y Marcos de grupo > Indicadores para indicadores de rol, amenaza, disipación, hechizo, esquina y marcador de incursión.",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "Utilice Marcos de grupo > Diseño para tamaño y espaciado, Mejoras y desventajas para desorden de aura e Indicadores para íconos de estado de posición fija.",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "Utilice páginas de marcos de grupo: Diseño para tamaño/growth/sorting, Salud y texto para barras/text, Mejoras y desventajas para auras e Indicadores para íconos de estado.",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "Utilice el modo de edición MSUF para arrastrar un marco de una sola unidad. Utilice la página de la unidad > Anclaje cuando necesite objetivos de anclaje exactos o valores X/Y.",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "Utilice el modo de edición MSUF para arrastrar barras de transmisión compatibles. Las opciones de habilitación de barra de transmisión por unidad/icon/text se encuentran en la página de cada unidad; El estilo de Castbar compartido está en Estilo global > Castbar.",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "Utilice el modo de edición MSUF para arrastrar el marco del reproductor. Para conocer los valores exactos de anclaje o X/Y, abra Reproductor > Anclaje después de eso.",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "Utilice los controles de escala del Panel para la escala del menú o la escala UI. También puedes cambiar el tamaño de la ventana MSUF2 desde su esquina.",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "Utilice la página de unidad para alternar barras de transmisión por unidad y Estilo global > Barra de transmisión para texturas compartidas, dirección, GCD, texto y opciones de interrupción.",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "Utilícelo si el desvanecimiento de la barra HP hace que el área de salud vacía desaparezca o se vea negra. Mantiene el mismo color de pista HP de Colors.",
    ["Value:"] = "Valor:",
    ["Version:"] = "Versión:",
    ["View"] = "Ver",
    ["Welcome to Class Resources!"] = "¡Bienvenido a Recursos de clase!",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW bloquea algunos cambios de marco protegidos en combate. Deja el combate, luego aplica cambios de diseño, anclaje, enable/disable, perfil o marco protegido.",
