    ["Auras 2.0 shared settings, per-unit aura overrides, filters, caps, layout, timer text and reminders"] = "Paramètres partagés Auras 2.0, remplacements d'aura par unité, filtres, majuscules, mise en page, texte de la minuterie et rappels",
    ["Auto"] = "Automatique",
