    ["Boss 4"] = "Patron 4",
    ["Boss 5"] = "Patron 5",
    ["Boss frames normally appear only during boss encounters. Enable Boss Frames and use Edit Mode or Boss Preview to test them outside combat."] = "Les cadres de boss n'apparaissent normalement que lors des rencontres de boss. Activez Boss Frames et utilisez le mode Édition ou Boss Preview pour les tester en dehors du combat.",
    ["Buff max: %d"] = "Buff maximum : %d",
    ["CDM + Class Power detected"] = "CDM + Classe Puissance détectée",
    ["CDM detected (no class resource for this spec)"] = "CDM détecté (aucune ressource de classe pour cette spécification)",
    ["CDM not visible - will center on screen"] = "CDM non visible - sera centré sur l'écran",
