    ["Changelog"] = "Journal des modifications",
    ["Chi"] = "Chi",
    ["Click to apply. Undo available in popup."] = "Cliquez pour postuler. Annuler disponible dans la fenêtre contextuelle.",
    ["Color"] = "Couleur",
    ["Combat"] = "Combattre",
    ["Confirm stages the reset; reload via /reload or MSUF Menu > Advanced > Factory Reset."] = "Confirmez les étapes de la réinitialisation ; rechargez via le menu /reload ou MSUF > Avancé > Réinitialisation d'usine.",
    ["Ctrl"] = "Ctrl",
