    ["Unit private aura controls are in Unit Auras > Private Auras. Group-frame private auras are in Group Frames > Buffs & Debuffs > Private Auras."] = "유닛 개인 오라 컨트롤은 유닛 오라(Unit Auras) > 프라이빗 오라(Private Auras)에 있습니다. 그룹 프레임 프라이빗 오라는 그룹 프레임 > 버프 및 디버프 > 프라이빗 오라에 있습니다.",
    ["Unitframes"] = "단위프레임",
    ["Urgent"] = "긴급",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "/msuf를 사용하여 MSUF2를 엽니다. 대시보드에는 재설정, 지원, 프로필 및 확장 도구도 포함되어 있습니다.",
    ["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "프레임 무버의 경우 대시보드 > 위치 재설정을 사용하십시오. 프로필 데이터를 재설정, 복사, 가져오기 또는 교체하려는 경우에만 프로필을 사용하십시오.",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "하이라이트 테두리에는 글로벌 스타일 > 바를 사용하고 역할, 위협, 해제, 주문, 코너 및 공격대 마커 표시에는 그룹 프레임 > 표시기를 사용하세요.",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "그룹 프레임 > 레이아웃을 사용하여 크기와 간격을 설정하고, 버프 및 디버프를 사용하여 오라 혼란을 해결하고, 표시기를 고정 위치 상태 아이콘으로 사용하세요.",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "그룹 프레임 페이지 사용: 크기 /growth/sorting 레이아웃, 막대 /text용 건강 및 텍스트, 오라용 버프 및 디버프, 상태 아이콘 표시기.",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "단일 단위 프레임을 드래그하려면 MSUF 편집 모드를 사용하십시오. 정확한 앵커 대상이나 X/Y 값이 필요한 경우 유닛 페이지 > 앵커링을 사용하세요.",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "지원되는 시전바를 드래그하려면 MSUF 편집 모드를 사용하세요. 유닛별 시전바 활성화/icon/text 옵션은 각 유닛 페이지에 있습니다. 공유 캐스트바 스타일은 글로벌 스타일 > 캐스트바에 있습니다.",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "MSUF 편집 모드를 사용하여 플레이어 프레임을 드래그하세요. 정확한 앵커 또는 X/Y 값을 보려면 그 후에 Player > Anchoring을 엽니다.",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "메뉴 배율 또는 UI 배율에는 대시보드 배율 컨트롤을 사용합니다. 모서리에서 MSUF2 창의 크기를 조정할 수도 있습니다.",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "유닛별 캐스트바 토글의 경우 유닛 페이지를 사용하고 공유 텍스처, 방향, GCD, 텍스트 및 인터럽트 옵션의 경우 전역 스타일 > Castbar를 사용하세요.",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "HP 바 페이드 현상으로 인해 빈 체력 영역이 사라지거나 검게 보이는 경우 이 기능을 사용하세요. Colors와 동일한 HP 트랙 색상을 유지합니다.",
    ["Value:"] = "값:",
    ["Version:"] = "버전:",
    ["View"] = "보기",
    ["Welcome to Class Resources!"] = "수업 자료에 오신 것을 환영합니다!",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW는 전투 중 일부 보호된 프레임 변경을 차단합니다. 전투를 떠난 후 레이아웃, 앵커링, /disable 활성화, 프로필 또는 보호 프레임 변경 사항을 적용하세요.",
    ["[2]"] = "[2]",
    ["aggro"] = "어그로",
    ["bottom"] = "바닥",
    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "클래스 리소스 레이아웃, 동작, 스타일, 자동 숨기기, 분리된 파워 바 및 대체 마나 설정",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "숨기려면 레이어 클릭 - 미리보기 요소 끌기 - 선택한 화살표로 이동",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "프레임 색상, 클래스/NPC 색상, 파워 색상, 시전바 색상, 오라 색상 및 게임플레이 색상 설정",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "전투 텍스트, 십자선, 클릭 시전 동작과 같은 게임플레이 향상 설정",
    ["gf_bars"] = "gf_bars",
    ["gf_mythicraid"] = "gf_mythicraid",
    ["gf_raid"] = "gf_raid",
    ["global castbar behavior, textures, GCD, boss castbar and interrupt indicator settings"] = "전역 시전바 동작, 텍스처, GCD, 보스 시전바 및 인터럽트 표시기 설정",
    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "언어/menu 동작, 업데이트 속도, 툴팁, Blizzard 프레임 처리, 미니맵 아이콘, 사운드 및 범위 페이드 설정",
    ["none"] = "없음",
    ["optional style/module settings such as MSUF Style and dropdown style"] = "MSUF 스타일 및 드롭다운 스타일과 같은 선택적 style/module 설정",
    ["scope disabled"] = "범위가 비활성화됨",
    ["shared"] = "공유됨",
    ["shared bar textures, gradients, rounded frame corners, absorb display, outlines, highlight borders, power smoothing and all per-unit/group bar overrides"] = "공유 막대 텍스처, 그라디언트, 둥근 프레임 모서리, 디스플레이 흡수, 윤곽선, 강조 테두리, 파워 스무딩 및 모든 단위당 /group 막대 재정의",
    ["shared font family, text style, name/power text coloring, name shortening and all per-unit/group font overrides"] = "공유 글꼴 모음, 텍스트 스타일, name/power 텍스트 색상 지정, 이름 단축 및 모든 단위당 /group 글꼴 재정의",
    ["the entire active profile"] = "전체 활성 프로필",
    ["|cff6EB5FFBuffs|r"] = "|cff6EB5FF버프|r",
    ["|cff6EB5FFDebuffs|r"] = "|cff6EB5FFDe버프|r",
