    ["Opens: Global Style > Colors"] = "打开：全局样式 > 颜色",
    ["Opens: Global Style > Colors > Bar Background Tint"] = "打开：全局样式 > 颜色 > 栏背景色调",
    ["Opens: Global Style > Colors > Bar Background Tint > Preserve HP color on all unit frames"] = "打开：全局样式 > 颜色 > 条形背景色调 > 在所有单元框架上保留 HP 颜色",
    ["Opens: Global Style > Colors > Bar Colors"] = "打开：全局样式 > 颜色 > 条形颜色",
    ["Opens: Global Style > Colors > Class Bar Colors"] = "打开：全局样式 > 颜色 > 类栏颜色",
    ["Opens: Global Style > Fonts"] = "打开：全局样式 > 字体",
    ["Opens: Global Style > Fonts > Name Shortening"] = "打开：全局样式 > 字体 > 名称缩写",
    ["Opens: Global Style > Fonts > Name Shortening / scope override"] = "打开：全局样式 > 字体 > 名称缩短/范围覆盖",
    ["Opens: Global Style > Miscellaneous"] = "打开：全局样式 > 其他",
    ["Opens: Global Style > Miscellaneous > Blizzard Frames"] = "打开：全局样式 > 其他 > Blizzard 框架",
