    ["Opens: Global Style > Miscellaneous > Menu behavior"] = "打开：全局样式 > 其他 > 菜单行为",
    ["Opens: Global Style > Miscellaneous > Range Fade"] = "打开：全局样式 > 其他 > 范围淡入淡出",
    ["Opens: Global Style > Miscellaneous > Unitframe tooltips"] = "打开：全局样式 > 其他 > 单位框架工具提示",
    ["Opens: Global Style > Miscellaneous > Update intervals"] = "打开：全局样式 > 其他 > 更新间隔",
    ["Opens: Global Style > Unit Auras"] = "打开：全局风格 > 单位光环",
    ["Opens: Group Frames > Buffs & Debuffs"] = "打开：组框架 > 增益和减益",
    ["Opens: Group Frames > Buffs & Debuffs > Aura Utilities"] = "打开：组框 > 增益和减益 > 光环实用程序",
